 public static void Install(LimboMatch m){if(GameObject.Find("Limbo festival coastline and lagoon")!=null)return;var root=new GameObject("Limbo festival coastline and lagoon").transform;var coast=new GameObject("Modeled sand island shoreline");coast.transform.SetParent(root,false);coast.transform.position=new Vector3(0,-.16f,23);coast.transform.localScale=new Vector3(85,2,80);coast.AddComponent<MeshFilter>().sharedMesh=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/TruckSumo/Models/Beveled continuous ring.asset");coast.AddComponent<MeshRenderer>().sharedMaterial=AssetDatabase.LoadAssetAtPath<Material>("Assets/TruckLimbo/Materials/Actual Vista beach sand.mat");var source=AssetDatabase.LoadAssetAtPath<Material>("Assets/TruckFishing/Materials/Clear fishing river.mat");string path="Assets/TruckLimbo/Materials/Festival turquoise lagoon.mat";var water=AssetDatabase.LoadAssetAtPath<Material>(path);if(water==null){water=new Material(source);water.name="Festival turquoise lagoon";water.SetColor("_BaseColor",new Color(.035f,.35f,.47f,.94f));water.SetFloat("_Smoothness",.75f);water.mainTextureScale=Vector2.one*180;AssetDatabase.CreateAsset(water,path);}var sea=GameObject.CreatePrimitive(PrimitiveType.Plane);sea.name="Surrounding animated turquoise lagoon";UnityEngine.Object.DestroyImmediate(sea.GetComponent<Collider>());sea.transform.SetParent(root,false);sea.transform.position=new Vector3(0,-.9f,23);sea.transform.localScale=new Vector3(1600,1,1600);sea.GetComponent<Renderer>().sharedMaterial=water;sea.AddComponent<LWS.TruckFishing.FishingWaterFlow>();
  for(int i=0;i<28;i++){float a=i*Mathf.PI*2/28;var rock=new GameObject("Owned coastal river rock "+i).transform;rock.SetParent(root,false);rock.position=new Vector3(Mathf.Cos(a)*80,-.23f,23+Mathf.Sin(a)*75);LWS.TruckKeepaway.Editor.KeepawayPresentationAuthoring.Fit(rock,"Assets/Layer Lab/3D Characters-Fish/Fish/Prefabs/Rock"+(char)('A'+i%3)+".prefab",new Vector3(4+i%3*1.4f,1.5f+i%2,3+i%3),0,false,"TruckLimbo");}
  const string table="Assets/Modern Resaturant - building and interior/Models/Prefabs/Restaurant_Table_Rectangular_1.prefab";var old=GameObject.Find("Tropical DJ mixing desk");if(old!=null){old.GetComponent<Renderer>().enabled=false;var model=new GameObject("Actual modeled DJ table").transform;model.SetParent(root,false);model.position=new Vector3(0,0,26);LWS.TruckKeepaway.Editor.KeepawayPresentationAuthoring.Fit(model,table,new Vector3(8,2.2f,2.8f),0,true,"TruckLimbo");var inset=GameObject.Find("Striped DJ desk inset");if(inset!=null)inset.GetComponent<Renderer>().enabled=false;}
  for(int i=0;i<8;i++){var patio=new GameObject("Festival beach seating "+i).transform;patio.SetParent(root,false);patio.position=new Vector3(i%2==0?-33:33,0,-10+i/2*18);LWS.TruckKeepaway.Editor.KeepawayPresentationAuthoring.Fit(patio,table,new Vector3(3,1.3f,2),0,false,"TruckLimbo");for(int side=-1;side<=1;side+=2){var chair=new GameObject("Actual patio chair").transform;chair.SetParent(patio,false);chair.localPosition=new Vector3(side*2,0,0);chair.localRotation=Quaternion.Euler(0,side>0?-90:90,0);LWS.TruckKeepaway.Editor.KeepawayPresentationAuthoring.Fit(chair,"Assets/Modern Resaturant - building and interior/Models/Prefabs/Restaurant_chair.prefab",new Vector3(1.1f,1.5f,1.1f),0,false,"TruckLimbo");}}
